/** Engine → host. The ring changed (first viewport, resize, GPU restart). Every slot of an older generation is gone; the host drops its imports of them. */
export interface FrameSlots {
  generation: number;
  viewport: number;
  width: number;
  height: number;
  format: PixelFormat;
  /** true: `handles` are NT handles valid in the host process (sharedTexture import); the ENGINE owns them — the host never closes one. false: offscreen slots (headless, tests); handles are 0. */
  shared: boolean;
  /** One per slot, at most 16. */
  handles: number[];
}

/** Engine → host. A finished frame is in `slot` (the GPU work is complete: Electron's rgba import takes no fence). The slot belongs to the host until it sends FrameRelease for this generation + slot. */
export interface FrameReady {
  generation: number;
  slot: number;
  viewport: number;
  /** Frames not delivered since the previous FrameReady (ring full, or the clock ran ahead of the GPU). */
  dropped: number;
  /** Comp frame index. */
  frame: number;
  time: Time;
  /** Document revision the frame shows. */
  revision: Revision;
  /** Epoch microseconds — MEASUREMENT ONLY, never an input to pixels. */
  renderStartUs: number;
  renderDoneUs: number;
  width: number;
  height: number;
}

/** Engine → host. Heartbeat answer, sent by the document core thread. */
export interface FramePong {
  nonce: number;
  revision: Revision;
  playing: boolean;
  /** Messages waiting in the core queue when the ping was served. */
  queued: number;
}

/** Host → engine. Chromium is done with a slot. A stale generation is ignored. */
export interface FrameRelease {
  generation: number;
  slot: number;
}

/** Host → engine. Heartbeat. */
export interface FramePing {
  nonce: number;
}

/** Every message on the frame channel (fd 3 / fd 4). Unknown variants are skipped by both sides. */
export type FrameChannelMessage =
  | ({ type: 'slots' } & FrameSlots)
  | ({ type: 'frameReady' } & FrameReady)
  | ({ type: 'pong' } & FramePong)
  | ({ type: 'release' } & FrameRelease)
  | ({ type: 'ping' } & FramePing);
export type FrameChannelMessageType = FrameChannelMessage['type'];

/** One field of an effect entry. Nested objects flatten to dotted names (`hostInputs.fps`). */
export interface RenderEffectParam {
  name: string;
  kind: RenderParamKind;
  number: number;
  numbers: number[];
  text: string;
  texts: string[];
}

/** One entry of a renderable's spatial effect chain (FrameScene RenderableEffect), by its `type` tag. */
export interface RenderEffect {
  type: string;
  params: RenderEffectParam[];
}

export interface RenderSdf {
  shape: RenderSdfShape;
  radiusPx: number;
  width: number;
  height: number;
}

export interface RenderColorMatrix {
  /** Row-major 3×3. */
  m: number[];
  offset: number[];
}

export interface RenderGlass {
  refraction: number;
  edgeWidth: number;
  aberration: number;
  saturation: number;
  tint: Color;
  tintOpacity: number;
  rim: Color;
  rimOpacity: number;
  rimWidth: number;
  rimAngle: number;
  specularAngle: number;
  specularIntensity: number;
  specularFalloff: number;
  grain: number;
}

export interface RenderMotionSample {
  modelMatrix: number[];
  opacity: number;
}

export interface RenderAdjustment {
  colorMatrix?: RenderColorMatrix;
  lutTextureKey?: string;
}

export interface RenderMatte {
  mode: RenderMatteMode;
  inverted: boolean;
  sourceId: string;
}

export interface RenderDeformedMesh {
  /** f32 LE, 4 floats per vertex (x, y, u, v). */
  vertices: Uint8Array;
  /** u16 LE. */
  triangles: Uint8Array;
  /** f32 LE, one per vertex; absent = flat. */
  depth?: Uint8Array;
}

export interface RenderGenerator {
  /** f32 LE, `stride` floats per instance. */
  instances: Uint8Array;
  count: number;
  stride: number;
  primitive: RenderGeneratorPrimitive;
  meshVertices?: Uint8Array;
  meshIndices?: Uint8Array;
  meshIndexFormat: RenderIndexFormat;
  textureKey?: string;
  cellSize: number[];
  blend: RenderGeneratorBlend;
  revision: number;
  width: number;
  height: number;
  perspective?: number;
}

export interface RenderMeshRange {
  role: RenderMeshRole;
  first: number;
  count: number;
  color: Color;
  gain: number;
  textured: boolean;
  textureKey?: string;
}

export interface RenderPbrMaps {
  normalKey?: string;
  metallicRoughnessKey?: string;
  occlusionKey?: string;
  emissiveKey?: string;
  normalScale: number;
  occlusionStrength: number;
  emissive: number[];
}

export interface RenderExtrudedMesh {
  key: string;
  /** f32 LE, 8 floats per vertex (position xyz, normal xyz, uv). */
  vertices: Uint8Array;
  indices: Uint8Array;
  indexFormat: RenderIndexFormat;
  ranges: RenderMeshRange[];
  pbr?: RenderPbrMaps;
}

export interface RenderShade3D {
  specular: number;
  shininess: number;
  metal?: number;
  roughness?: number;
  toonBands?: number;
  /** Empty = absent. */
  quadGain: number[];
  oneSided?: boolean;
  ambient?: number;
  diffuse?: number;
  reflectionIntensity?: number;
  reflectionSharpness?: number;
  reflectionRolloff?: number;
  transparency?: number;
  transparencyRolloff?: number;
  ior?: number;
  acceptsShadows?: boolean;
}

export interface RenderThreeD {
  /** Column-major 4×4. */
  model: number[];
  castsShadow?: boolean;
  shade?: RenderShade3D;
}

export interface RenderDof {
  strength: number;
  focus: number;
  aperture: number;
  focalLength?: number;
  fStop?: number;
  irisBlades?: number;
  irisRoundness?: number;
  highlightGain?: number;
  irisRotation?: number;
  irisAspect?: number;
  highlightThreshold?: number;
  highlightSaturation?: number;
  diffractionFringe?: number;
}

export interface RenderCamera3D {
  view: number[];
  projection: number[];
  /** Empty = ortho (no eye). */
  eye: number[];
  dof?: RenderDof;
}

export interface RenderLight3D {
  type: RenderLightType;
  /** r, g, b. */
  color: number[];
  gain: number;
  x: number;
  y: number;
  z: number;
  radius: number;
  aimX: number;
  aimY: number;
  aimZ: number;
  halfConeRad: number;
  coneFeatherRad: number;
  falloffMode: number;
  falloffDistance: number;
  shadowMap?: boolean;
  shadowMapSize?: number;
  shadowBias?: number;
  shadowSoftness?: number;
  shadowDarkness?: number;
}

export interface RenderEnvMap {
  id: string;
  width: number;
  height: number;
  levels: number;
  scale: number;
  /** RGBA8. */
  data: Uint8Array;
  intensity: number;
  rotationDeg: number;
}

export interface RenderSsao {
  enabled: boolean;
  radius: number;
  intensity: number;
  quality: RenderSsaoQuality;
}

/** An isolated precomp's own frame (FrameScene `Renderable.precomp` minus its children, which ride on the renderable as `precompChildren`). */
export interface RenderPrecompFrame {
  camera3d?: RenderCamera3D;
  lights3d: RenderLight3D[];
  envMap?: RenderEnvMap;
  /** A 3D composition card: children are in the comp's own pixels. */
  flatWidth?: number;
  flatHeight?: number;
}

/** FrameScene `Renderable`. */
export interface Renderable {
  id: string;
  kind: RenderableKind;
  /** Mat3, column-major, 9 float32 values. */
  modelMatrix: number[];
  bounds: Rect;
  opacity: number;
  blend: RenderBlendMode;
  advancedBlend?: number;
  preserveTransparency: boolean;
  depthExempt: boolean;
  backdropBlur?: number;
  glass?: RenderGlass;
  sampling: RenderSampling;
  color?: Color;
  sdf?: RenderSdf;
  colorMatrix?: RenderColorMatrix;
  effects: RenderEffect[];
  textureKey?: string;
  uvRect?: Rect;
  clip: boolean;
  motionSamples: RenderMotionSample[];
  /** 8 numbers (TL, TR, BR, BL); empty = no pin. */
  cornerPin: number[];
  maskId?: string;
  maskTextureKey?: string;
  lutTextureKey?: string;
  adjustment?: RenderAdjustment;
  matte?: RenderMatte;
  matteSource: boolean;
  lightWash: boolean;
  precomp?: RenderPrecompFrame;
  precompChildren: Renderable[];
  generator?: RenderGenerator;
  deformedMesh?: RenderDeformedMesh;
  extrudedMesh?: RenderExtrudedMesh;
  threeD?: RenderThreeD;
}

/** FrameScene. */
export interface RenderFrameScene {
  compositionId: string;
  width: number;
  height: number;
  background?: Color;
  renderables: Renderable[];
  hasEffects: boolean;
  dissolveFrame?: number;
  camera3d?: RenderCamera3D;
  lights3d: RenderLight3D[];
  envMap?: RenderEnvMap;
  ssao?: RenderSsao;
}

/** One user guide (OverlayPass). */
export interface RenderGuide {
  axis: RenderGuideAxis;
  position: number;
  color?: Color;
}

/** Viewport overlays (Viewport.overlays): the grid, the proportional grid and user guides. Editor chrome only. */
export interface RenderOverlays {
  grid: boolean;
  gridSpacing: number;
  gridSubdivisions: number;
  gridStyle: RenderGridStyle;
  /** Absent = OverlayPass.gridColor. */
  gridColor?: Color;
  proportionalGrid: boolean;
  proportionalColumns: number;
  proportionalRows: number;
  /** The comp rect in world units (proportional grid). */
  compRect?: Rect;
  guides: RenderGuide[];
}

/**
 * The viewer/monitor LUT (colorPipeline.ts ViewerLutMeta), applied after the display transform on the viewport only.
 * Its strip rides as the texture key `viewer-lut`.
 */
export interface RenderViewerLut {
  size: number;
  is1d: boolean;
  intensity: number;
  domainMin: number;
  domainMax: number;
}

/**
 * D3 colour management, After Effects' model: the project's working space (compositing is always linear light —
 * AE's "Linearize Working Space" is always on — in the working space's primaries), each footage item's input
 * interpretation (RenderTextureRef.inputSpace), the viewer's display transform, and the output module's transform.
 * Applied as GPU passes built from OpenColorIO. ABSENT = today's pipeline (workingSpace/displayTransform), byte for byte.
 */
export interface RenderColorManagement {
  workingSpace: RenderColorSpace;
  /** The viewer's display. */
  displaySpace: RenderColorSpace;
  /** Set on an export frame: the output module's space, in place of displaySpace. */
  outputSpace?: RenderColorSpace;
  /** An OCIO view on the display (e.g. an ACES output transform); absent = the plain encode into displaySpace. */
  view?: string;
  /** OCIO config (file path or ocio:// URI); absent = OCIO's built-in CG config. */
  ocioConfig?: string;
}

/** The viewport a FrameScene is drawn through, and the colour pipeline state the frame was rendered with. */
export interface RenderView {
  /** CSS size and device pixel ratio (Viewport); the framebuffer is round(css × dpr). */
  cssWidth: number;
  cssHeight: number;
  devicePixelRatio: number;
  /** Camera2D state: world point at the viewport centre, screen px per world unit. */
  cameraCenterX: number;
  cameraCenterY: number;
  cameraZoom: number;
  /** overlays.background — the ClearPass colour (display-referred). */
  clearColor: Color;
  /** Surface scissor (surface px, top-left origin); absent = none. */
  frameClip?: Rect;
  /** Any grid / proportional grid / guide overlay is on (OverlayPass would draw). */
  overlaysActive: boolean;
  workingSpace: RenderWorkingSpace;
  displayTransform: RenderDisplayTransform;
  /** Intermediate float depth: 16 or 32. */
  bitDepth: number;
  float16Textures: boolean;
  float32Textures: boolean;
  surfaceFormat: RenderTextureFormat;
  /** A viewer LUT is active on the final blit (viewport-only; exports leave it off). */
  viewerLutActive: boolean;
  /** The GPU the producer rendered on (WebGPU adapter vendor, e.g. "amd", "nvidia"); a parity consumer renders on the same one. */
  adapterVendor?: string;
  /** What the overlay pass draws, when overlaysActive. */
  overlays?: RenderOverlays;
  /** The viewer LUT's parameters, when viewerLutActive. */
  viewerLut?: RenderViewerLut;
  /** D3 colour management; absent = today's pipeline. */
  colorManagement?: RenderColorManagement;
}

/** A texture key the scene samples → the content it resolved to when the frame was rendered. */
export interface RenderTextureRef {
  key: string;
  /** RenderBlob.hash; empty = the key did not resolve (the renderer skips the draw, as the TS one does). */
  hash: string;
  /** Already working-space (float EXR, graph RTs): skips the sRGB decode on sample. */
  sampleLinear: boolean;
  ready: boolean;
  /**
   * D3: how this COLOUR texture's texels are encoded (Interpret Footage ▸ Color). Under colorManagement a tagged
   * texture is converted once into working-space linear light; untagged textures are data (masks, LUT strips,
   * displacement / normal maps) and are never converted.
   */
  inputSpace?: RenderColorSpace;
}

/** Texel content, stored once per distinct hash. Rows top-down, tightly packed. */
export interface RenderBlob {
  hash: string;
  width: number;
  height: number;
  format: RenderTextureFormat;
  pixels: Uint8Array;
  /** The GPU texture carried a mip chain (only level 0 is stored; the consumer regenerates). */
  mipmapped: boolean;
}

/** WGSL for a shader the scene names that is NOT a renderer builtin — a plugin effect's host-validated source, as registered with the TS ShaderRegistry. */
export interface RenderShaderSource {
  name: string;
  wgsl: string;
}

/**
 * E3: what a text / vector raster was drawn FROM, so the C++ rasterizer (native/engine/src/raster) can draw it again
 * and be compared with the TS texels in `blobs` — the parity harness, not a runtime path. The C++ engine will build
 * the same description in process from its own document.
 */
export interface RenderRasterSource {
  /** The texture key (RenderTextureRef.key) the raster was bound to when the frame rendered. */
  key: string;
  kind: RenderRasterKind;
  /** The TS rasterizer's cache key (Canvas2DVectorRasterizer). */
  cacheKey: string;
  /** The raster canvas (= texture) size in px. */
  width: number;
  height: number;
  /** Canvas2DVectorRasterizer's inputs: raster scale (tier × supersample decided inside) and padding in layer px. */
  resolutionScale: number;
  padding: number;
  /** The drawable the painter read — a TextSpec or a RenderLayer — as JSON. */
  specJson: string;
  /**
   * The Canvas2D calls the painter issued, recorded, as JSON (grammar: native/engine/src/raster/canvas_replay.hpp).
   * Empty when the harness did not record them.
   */
  opsJson: string;
  /** Why the recording cannot be replayed exactly ('' = it can), e.g. a CPU-baked effect chain read back pixels. */
  incomplete: string;
}

/** One frame, self-contained: `premation-render --scene <file>` renders it with no other input. */
export interface RenderFrameFile {
  /** Bumped when the exporter's mapping changes meaning (not for additive fields). */
  formatVersion: number;
  sceneId: string;
  frame: number;
  view: RenderView;
  scene: RenderFrameScene;
  textures: RenderTextureRef[];
  blobs: RenderBlob[];
  /** Plugin effect shaders the frame uses (effect param `shader`), by name. */
  shaders: RenderShaderSource[];
  /** E3: the source of every text / vector raster in `textures` the harness captured (empty otherwise). */
  rasters: RenderRasterSource[];
}

